<script>
 import {keyboardRows,INPUT_SOURCES} from './input-model.js';
 let {session,input,accessibility,command}=$props();
 const rows=$derived(keyboardRows(input?.activeSourceId,{shift:session.shift,option:session.option}));
</script>
{#if session.keyboard||session.viewer}<section class="vo-keyboard" aria-label={session.viewer?'Keyboard Viewer':'Accessibility Keyboard'}><header><strong>{session.viewer?'Keyboard Viewer':'Accessibility Keyboard'} — {INPUT_SOURCES.find(s=>s.id===input?.activeSourceId)?.name}</strong><button aria-label="Close keyboard" onclick={()=>command('auxiliary',{keyboard:false,viewer:false})}>×</button></header>{#each rows as row}<div>{#each row as key}<button data-av-control={`key:${key.keyId}`} aria-label={key.label} aria-pressed={key.action==='modifier'?(key.keyId==='Shift'?session.shift:session.option):undefined} onmousedown={e=>e.preventDefault()} onclick={()=>command('key',{keyId:key.keyId})}>{key.label}</button>{/each}</div>{/each}<small>Uses the original local input source. Inserts only into the focused Reading Preview; no host keyboard or IME changes.</small></section>{/if}
{#if accessibility?.captions&&session.caption}<aside class="vo-caption" class:large={accessibility.captionsStyle==='large'} class:classic-caption={accessibility.captionsStyle==='classic'} aria-label="Local reading captions" role="status">{session.caption}</aside>{/if}
{#if accessibility?.zoom}<aside class="vo-zoom-overlay" aria-label="Local reading zoom overlay"><header>Local text magnifier · {accessibility.zoomScale}× <button aria-label="Close local zoom" onclick={()=>command('settings',{zoom:false})}>×</button></header><div style:font-size={`${13*accessibility.zoomScale}px`}>{session.readingText||'The Reading Preview is empty.'}</div></aside>{/if}
<style>
 .vo-zoom-overlay{position:sticky;bottom:8px;margin:12px 0;padding:10px;background:#fff;color:#111;border:3px solid #111;box-shadow:0 6px 18px #0005;border-radius:6px;z-index:2}.vo-zoom-overlay header{display:flex;justify-content:space-between;font-size:10px;border-bottom:1px solid #aaa;padding-bottom:5px;margin-bottom:8px}.vo-zoom-overlay header button{border:0;background:none;font-size:16px}.vo-zoom-overlay>div{white-space:pre-wrap;overflow:auto;max-height:180px;line-height:1.5}
 .vo-keyboard{padding:10px;background:#d8d9dc;border:1px solid #a3a4a8;border-radius:6px;margin-top:12px}.vo-keyboard header{display:flex;justify-content:space-between;font-size:11px;margin-bottom:8px}.vo-keyboard>div{display:flex;gap:3px;margin:3px 0}.vo-keyboard button{flex:1;min-width:24px;min-height:29px;border:1px solid #9fa0a4;border-radius:4px;background:linear-gradient(#fff,#dedfe1);font-size:11px;box-shadow:0 1px 1px #999}.vo-keyboard button[aria-pressed=true]{background:#458ddd;color:white}.vo-keyboard header button{flex:0;min-height:20px}.vo-keyboard small{display:block;font-size:10px;margin-top:8px}.vo-caption{position:sticky;bottom:4px;background:#181818;color:#fff;border:1px solid #777;border-radius:6px;padding:12px;margin:8px 0;white-space:pre-wrap;max-height:150px;overflow:auto;font:16px/1.4 'Helvetica Neue',sans-serif}.vo-caption.large{font-size:23px}.vo-caption.classic-caption{font-family:monospace;border-radius:0}.vo-keyboard button:focus-visible{outline:3px solid #157acc}
</style>
